CREATE TABLE search_documents(workspace_id uuid NOT NULL,id uuid NOT NULL,resource_type text NOT NULL,resource_id uuid NOT NULL,visibility_epoch bigint NOT NULL DEFAULT 0,search_text tsvector NOT NULL,display_fields jsonb NOT NULL CHECK(jsonb_typeof(display_fields)='object'),field_visibility jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),deleted_at timestamptz,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,resource_type,resource_id));
CREATE INDEX search_documents_text_idx ON search_documents USING gin(search_text);CREATE INDEX search_documents_resource_idx ON search_documents(workspace_id,resource_type,updated_at DESC);
CREATE TABLE recent_resources(workspace_id uuid NOT NULL,user_id uuid NOT NULL,id uuid NOT NULL,resource_type text NOT NULL,resource_id uuid NOT NULL,last_opened_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,user_id,id),UNIQUE(workspace_id,user_id,resource_type,resource_id));
CREATE TABLE saved_views(workspace_id uuid NOT NULL,id uuid NOT NULL,owner_user_id uuid NOT NULL REFERENCES users(id),resource_type text NOT NULL,name text NOT NULL,visibility text NOT NULL CHECK(visibility IN('private','workspace')),definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object'),schema_version integer NOT NULL DEFAULT 1,is_default boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
CREATE INDEX saved_views_owner_idx ON saved_views(workspace_id,owner_user_id,resource_type);
CREATE TABLE metric_definitions(workspace_id uuid NOT NULL,id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object'),state text NOT NULL CHECK(state IN('draft','published','superseded')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,key,version));
CREATE TABLE metric_buckets(workspace_id uuid NOT NULL,id uuid NOT NULL,metric_key text NOT NULL,metric_version integer NOT NULL,bucket_start timestamptz NOT NULL,bucket_end timestamptz NOT NULL,dimensions jsonb NOT NULL DEFAULT '{}'::jsonb,value numeric(30,9) NOT NULL,contributing_count bigint NOT NULL,source_watermark timestamptz NOT NULL,corrected_at timestamptz,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,metric_key,metric_version,bucket_start,dimensions));
CREATE INDEX metric_buckets_query_idx ON metric_buckets(workspace_id,metric_key,bucket_start DESC);
CREATE TABLE reports(workspace_id uuid NOT NULL,id uuid NOT NULL,owner_user_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object'),visibility text NOT NULL CHECK(visibility IN('private','workspace')),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','archived')),revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
CREATE TABLE report_exports(workspace_id uuid NOT NULL,id uuid NOT NULL,report_id uuid NOT NULL,state text NOT NULL CHECK(state IN('queued','building','ready','failed','expired','cancelled')),format text NOT NULL CHECK(format IN('csv','pdf')),row_count bigint,object_reference text,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,report_id) REFERENCES reports(workspace_id,id));
CREATE TABLE report_schedules(workspace_id uuid NOT NULL,id uuid NOT NULL,report_id uuid NOT NULL,cadence text NOT NULL,time_zone text NOT NULL,next_delivery_at timestamptz,state text NOT NULL CHECK(state IN('active','paused')),revision integer NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,report_id) REFERENCES reports(workspace_id,id));
CREATE TABLE product_analytics_events(workspace_id uuid NOT NULL,id uuid NOT NULL,event_name text NOT NULL,schema_version integer NOT NULL,anonymous_subject_hash text NOT NULL,properties jsonb NOT NULL CHECK(jsonb_typeof(properties)='object'),consent_state text NOT NULL CHECK(consent_state IN('essential','measurement')),occurred_at timestamptz NOT NULL,PRIMARY KEY(workspace_id,id));
DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['search_documents','recent_resources','saved_views','metric_definitions','metric_buckets','reports','report_exports','report_schedules','product_analytics_events'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',table_name);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',table_name);EXECUTE format('CREATE POLICY %I_tenant ON %I USING (knotline_tenant_visible(workspace_id)) WITH CHECK (knotline_tenant_visible(workspace_id))',table_name,table_name);END LOOP;END $$;
REVOKE ALL ON search_documents,recent_resources,saved_views,metric_definitions,metric_buckets,reports,report_exports,report_schedules,product_analytics_events FROM PUBLIC;GRANT SELECT,INSERT,UPDATE,DELETE ON search_documents,recent_resources,saved_views,reports,report_exports,report_schedules TO knotline_runtime;GRANT SELECT,INSERT,UPDATE ON metric_definitions,metric_buckets,product_analytics_events TO knotline_runtime;GRANT SELECT ON search_documents,saved_views,metric_definitions,metric_buckets,reports,report_exports,report_schedules TO knotline_reporting;
